export const POINCARE_BALL_EPS = 1e-10;
export const MAX_NORM = 1 - POINCARE_BALL_EPS;

export const RESOURCE_LIMITS = {
  MAX_NODES: 1_000_000,
  MAX_EDGES: 10_000_000,
  MAX_DIMENSIONS: 512,
